1	export type Cell = [number, number];
2	
3	const SURVIVAL_NEIGHBOUR_COUNTS = [2, 3];
4	const BIRTH_NEIGHBOUR_COUNT = 3;
5	
6	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
7	
8	const isSameCell = (cell: Cell, other: Cell): boolean =>
9	  keyOf(cell) === keyOf(other);
10	
11	const neighboursOf = ([x, y]: Cell): Cell[] =>
12	  [-1, 0, 1].flatMap((dx) =>
13	    [-1, 0, 1]
14	      .filter((dy) => dx !== 0 || dy !== 0)
15	      .map((dy): Cell => [x + dx, y + dy]),
16	  );
17	
18	const isNeighbour = (cell: Cell, other: Cell): boolean =>
19	  neighboursOf(cell).some((neighbour) => isSameCell(neighbour, other));
20	
21	const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
22	  liveCells.filter((other) => isNeighbour(cell, other)).length;
23	
24	const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
25	  liveCells.some((live) => isSameCell(cell, live));
26	
27	const uniqueCells = (cells: Cell[]): Cell[] => [
28	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
29	];
30	
31	const deadNeighboursOf = (liveCells: Cell[]): Cell[] =>
32	  uniqueCells(
33	    liveCells.flatMap(neighboursOf).filter((cell) => !isLive(cell, liveCells)),
34	  );
35	
36	export function nextGeneration(liveCells: Cell[]): Cell[] {
37	  const survivors = liveCells.filter((cell) =>
38	    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, liveCells)),
39	  );
40	
41	  const births = deadNeighboursOf(liveCells).filter(
42	    (cell) => countLiveNeighbours(cell, liveCells) === BIRTH_NEIGHBOUR_COUNT,
43	  );
44	
45	  return [...survivors, ...births];
46	}
