1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	const sorted = (cells: Cell[]): Cell[] =>
5	  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);
6	
7	describe("Game of Life - Next Generation", () => {
8	  it("returns an empty grid for an empty grid — [] -> []", () => {
9	    expect(nextGeneration([])).toEqual([]);
10	  });
11	  it("kills a single lonely cell — [(0,0)] -> []", () => {
12	    expect(nextGeneration([[0, 0]])).toEqual([]);
13	  });
14	  it("Rule 1 Underpopulation: kills two cells that each have 1 neighbor — [(0,1),(1,1)] -> []", () => {
15	    expect(
16	      nextGeneration([
17	        [0, 1],
18	        [1, 1],
19	      ]),
20	    ).toEqual([]);
21	  });
22	  it("Rule 2 Survival: a live cell with 3 live neighbors lives on — (1,1) survives", () => {
23	    const next = nextGeneration([
24	      [0, 0],
25	      [1, 0],
26	      [2, 0],
27	      [1, 1],
28	    ]);
29	
30	    expect(next).toContainEqual([1, 1]);
31	  });
32	  it("Rule 3 Overpopulation: a live cell with more than 3 live neighbors dies — (1,1) absent", () => {
33	    const next = nextGeneration([
34	      [0, 0],
35	      [1, 0],
36	      [2, 0],
37	      [1, 1],
38	      [0, 2],
39	      [1, 2],
40	      [2, 2],
41	    ]);
42	
43	    expect(next).not.toContainEqual([1, 1]);
44	  });
45	  it("Rule 4 Reproduction: a dead cell with exactly 3 live neighbors becomes alive — (1,1) is born", () => {
46	    const next = nextGeneration([
47	      [0, 0],
48	      [1, 0],
49	      [0, 1],
50	    ]);
51	
52	    expect(next).toContainEqual([1, 1]);
53	  });
54	  it("Block still life stays unchanged — [(0,0),(1,0),(0,1),(1,1)] -> same 4 cells", () => {
55	    const block: Cell[] = [
56	      [0, 0],
57	      [1, 0],
58	      [0, 1],
59	      [1, 1],
60	    ];
61	
62	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
63	  });
64	  it("Blinker oscillates vertical to horizontal — [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]", () => {
65	    const next = nextGeneration([
66	      [0, 0],
67	      [0, 1],
68	      [0, 2],
69	    ]);
70	
71	    expect(sorted(next)).toEqual(
72	      sorted([
73	        [-1, 1],
74	        [0, 1],
75	        [1, 1],
76	      ]),
77	    );
78	  });
79	  it.todo(
80	    "Blinker returns to vertical after two generations — [(-1,1),(0,1),(1,1)] -> [(0,0),(0,1),(0,2)]",
81	  );
82	  it.todo(
83	    "handles negative coordinates — blinker at negative offset oscillates the same way",
84	  );
85	});
