const countLiveNeighbours = (cell: Cell, liveKeys: Set<string>): number =>
  neighboursOf(cell).filter((neighbour) => liveKeys.has(keyOf(neighbour)))
    .length;

const uniqueCells = (cells: Cell[]): Cell[] => [
  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
];

const deadNeighboursOf = (liveCells: Cell[], liveKeys: Set<string>): Cell[] =>
  uniqueCells(
    liveCells.flatMap(neighboursOf).filter((cell) => !liveKeys.has(keyOf(cell))),
  );

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveKeys = new Set(liveCells.map(keyOf));

  const survivors = liveCells.filter((cell) =>
    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, liveKeys)),
  );

  const births = deadNeighboursOf(liveCells, liveKeys).filter(
    (cell) => countLiveNeighbours(cell, liveKeys) === BIRTH_NEIGHBOUR_COUNT,
  );

  return [...survivors, ...births];
}
